insert into public.publishers (exhibitor_no, booth_number, original_booth_number, name, name_en, country_ko, country_en, is_special, categories, introduction, homepage, instagram, sort_order) values
  (366, 'B504', null, '내로라 출판사', 'The Naerora Bookmakers', null, null, false, array['예술','언어','문학']::text[], '내로라한 문학생활 전집으로 문학을 읽는 또 다른 방식을 제안합니다. 영미 고전 단편소설을 원서와 함께 담고, 사람과 세상을 이해하는 재료로 삼을 수 있도록 여러 겹의 해설을 더했습니다. 독자가 공감하고 변화할 때 문학은 비로소 완성된다고 믿습니다.', null, 'https://Instagram.com/naeroras/', 366),
  (367, 'B504', null, '니라이카나이', 'NIRAIKANAI', null, null, false, array['총류','문학']::text[], '독자들을 책이라는 낙원으로 잇는 다리가 되겠다는 마음을 담아 시작한 나 홀로 출판사입니다. ‘니라이카나이’는 오키나와 방언으로 ‘바다 건너 저편의 낙원’을 뜻합니다. 실제로 오키나와에 있는 다리 이름이기도 하고요. 읽고 좋았던 일본 에세이를 손수 번역해 소개하고 있습니다. 천천히 마음을 포개며 읽게 되는 책을 만들고자 합니다.', null, 'https://instagram.com/niraikanai_books/', 367),
  (368, 'B504', null, '도깨비사', 'dokebisha', null, null, false, array['총류','사회과학','문학']::text[], '도깨비사는 일인 리틀프레스로 이주자의 시선으로 담아낸 일러스트와 에세이, 로컬 문화와 언어 학습을 잇는 특별한 콘텐츠를 기획하고 제작합니다.', null, 'https://www.instagram.com/dokebisha/', 368),
  (369, 'B504', null, '두두플래닛', 'Dodoplanet', null, null, false, array['예술','아동']::text[], '두두플래닛는 서울에 위치한 독립출판사입니다. ''두두''라는 이름은 심장박동 소리 ''두근두근''에서 왔습니다. 이 세상이 두근두근행성이 되기를 바라며, 살아 있는 모든 존재를 향한 경이로운 마음을 담아 책을 만듭니다. 어린이 그림책 임프린트 거의동그라미를 운영하고 있습니다.', 'https://www.almostdongrami.kr/', null, 369),
  (370, 'B504', null, '두유라이크', 'DO! U LIKE', null, null, false, array['예술']::text[], '좋아하는 모든 것을 함께합니다. 책으로 만나는 감성 놀이, 두유라이크 두유라이크는 독자들이 좋아하는 것을 묻고, 좋아하는 것을 함께하자는 메시지를 전달하고 싶은 출판사이자 콘텐츠사입니다. 책과 다양한 매체와의 믹스매치를 통해 책 놀이의 새로운 가능성을 모색하고자 합니다.', null, 'https://www.instagram.com/doulike_books/', 370),
  (371, 'B504', null, '리케의 디자인랩', 'lidilab', null, null, false, array['예술']::text[], '디자인과 글을 기반으로 개인의 경험과 감정을 기록하고 확장하는 독립 출판사입니다. 예술, 문학, 필사 콘텐츠를 중심으로 시각과 언어가 결합된 결과물을 제작하며, 일상 속 사유를 깊이 있게 풀어내는 작업을 지향합니다. 단순한 콘텐츠 생산을 넘어 창작자의 시선과 태도를 담은 책을 기획·출판하며, 감각적인 디자인과 밀도 있는 텍스트를 통해 독자와의 지속적인 연결을 만들어갑니다.', 'http://www.lidilab.com', null, 371),
  (372, 'B504', null, '마리유니버스', 'Mariuniverse', null, null, false, array['문학','아동']::text[], '마리유니버스는 창작 그림책 전문 출판사입니다. 우리는 이야기 우주에서 빛나는 영감을 주는 작가님들을 찾아내어 그들의 작품을 아름답고 정성스럽게 제작된 그림책으로 제작하고 있습니다. 남몰래 간직한 작고 소중한 이야기를 다양한 방식으로 독자들에게 선물하며 생명력을 불어넣고 있습니다. 또한, 우리는 그림책의 가치를 확대하여 일러스트, 캐릭터, 웹툰, 디자인 굿즈 등 다양한 형태의 콘텐츠로 발전시켜 독자들에게 더 큰 즐거움을 제공합니다. 우리는 새로운 영감을 함께 탐구하고 예술과 스토리텔링의 융합을 통해 문화적 가치를 높이는 데 힘쓰고 있습니다.', null, 'https://www.instagram.com/mariuniverse.book/', 372),
  (373, 'B504', null, '머핀북', 'MuffinbooK', null, null, false, array['아동','전자출판']::text[], '초등 대상의 지식 교양서와 동화를 주로 펴내는 어린이 출판사입니다. (26년 3월 기준, 26종 출간-동화 8종, 지식교양서 18종) 즐거운 이야기 속에 바른 인성 함양, 생명 존중과 환경보호 메시지를 담아 책임 있는 사회인으로 성장하는 데 도움이 되는 책을 펴내고 있습니다. 자사 도서 중 가 대만으로 판권 수출되었습니다.', null, 'https://www.instagram.com/muffinbook2022/', 373),
  (374, 'B504', null, '무블출판사', 'MOBL Books', null, null, false, array['총류','사회과학','문학']::text[], '무블출판사는 문학도서를 출판하는 무불(無不), 그리고 비문학 임프린트 무블북스(MOBL Books)를 통해 다양한 장르와 주제를 선보이는 출판사입니다. ‘무불’은 한자로 無不, 다시 말해 ‘~ 아닌 것이 없다’ 혹은 ‘모두 ~이다’라는 뜻으로, ‘無不貴’처럼 귀하고 아름다운, 유의미한 콘텐츠만을 선보이겠다는 의지를 담습니다. 현재까지 문학/인문학 부문 22권, 부동산부문 5권, 사회-경제경영 부문 10권을 출간했습니다.', 'http://mobl.kr', null, 374),
  (375, 'B504', null, '무중력프레스', 'Zero Gravity Press', null, null, false, array['문학']::text[], '‘무중력프레스’는 자유를 사랑하는 이들을 위한 독립 출판사입니다. 세상이 씌운 중력의 사슬에서 벗어나 자유로이 유영하는 일상의 편린들을 한 권 한 권의 궤적으로 남기겠다는 뜻을 품고 있습니다. 무중력프레스는 무수한 편견들을 등지고, 유연한 몸짓으로 세상을 유영하는 방법을 담대하게 담아냅니다. 더불어 팍팍한 현실 속에서도 묵묵히 한 줌의 온기를 지켜내는 사람들의 따스한 일상을 빼곡히 적어냅니다. 진솔하게 펴낸 작가의 감정과 경험이 독자들과 만나, 생동감 넘치는 삶으로 나아가는 단단한 방향키가 될 수 있음을 믿기 때문입니다. 그 믿음 위에서 차곡차곡 만들어온 이야기들을 2026년 서울국제도서전에서 첫 책으로 선보입니다. 힘차게 유영하는 독자들과 함께 더 깊고 넓은 우주를 만들어 가보려 합니다.', null, 'https://www.instagram.com/mjr_press/', 375),
  (376, 'B504', null, '물숨', 'moolsoom', null, null, false, array['사회과학','예술','문학']::text[], '물 안팎에서 숨쉬며 생존과 용기, 기쁨을 이야기하는 책을 만듭니다.', null, 'https://www.instagram.com/moolsoom/', 376),
  (377, 'B504', null, '밤두', 'bamdoo press', null, null, false, array['총류','예술','언어']::text[], '밤두는 동시대 예술과 건축, 이미지 기반 작업을 출판의 형식으로 기록하고 유통하는 독립 아트북 출판사이자 퍼블리싱 플랫폼이다. 출판을 매개로 예술가, 건축가, 독자가 느슨하게 연결되는 유동적인 허브를 지향한다. 밤두는 책을 단순한 기록물이 아니라 지속적으로 확장되는 담론의 구조로 바라보며, 독립출판이라는 형식을 통해 예술 실천의 속도와 규모를 넓혀가고자 한다. 책을 만들고, 전시를 기획하고, 때로는 작은 파티를 열며 출판을 중심으로 다양한 만남의 장을 만든다. 이를 통해 이미지와 텍스트, 사람과 공간 사이의 관계를 새롭게 엮고 재구성하고자 한다.', 'http://bamdoo.kr', null, 377),
  (378, 'B504', null, '북스토어블', 'bookstorable', null, null, false, array['예술','문학']::text[], '북스토어블은 개인의 기록에 의미를 더해 종이 위에 담습니다. 주로 동물과 여성을 주제로 한 책을 출판하며, 비정기적 독서모임과 진(zine) 워크숍을 운영합니다.', null, 'https://www.instagram.com/bookstorable/', 378),
  (379, 'B504', null, '붉은사슴', 'Red Deer', null, null, false, array['예술','문학']::text[], '붉은사슴은 문학·예술 분야의 출판물을 기획·제작하는 1인 출판사이자 디자인 스튜디오입니다. 감각과 사유가 작동하는 책을 만들며 물성을 고려한 출판물을 통해 독자가 책을 새롭게 경험할 수 있도록 합니다. 그래픽 디자인 작업을 바탕으로 책과 연결된 인쇄물을 제작하여 출판의 외연을 확장하고 책을 보다 다층적으로 전달합니다.', null, 'https://instagram.com/red.deer.books/', 379),
  (380, 'B504', null, '빛틈', 'vitteum', null, null, false, array['철학','문학']::text[], '빛틈은 퀴어, 인문, 예술 분야의 경계에서 우리 사회의 가려진 서사를 발굴하고 기록하는 출판사입니다. 퀴어 당사자의 삶을 깊이 있게 조명하는 서사부터 예술적 통찰이 담긴 인문 에세이까지, 소수자의 목소리가 지워지지 않도록 정성껏 책을 짓습니다. 특히 삶과 예술, 그리고 마음을 잇는 독보적인 콘텐츠를 통해, 다양성의 가치를 실현하기 위해 애쓰고 있습니다. 단순한 도서 출간을 넘어, 책이라는 ''틈''을 통해 세상의 편견을 허물고 인문학적 성찰과 예술적 영감을 공유하는 지식의 장을 지향합니다.', null, 'https://instagram.com/vitteum/', 380),
  (381, 'B504', null, '생각하는 달팽이', 'Thinking Snail', null, null, false, array['문학','기타(그림 에세이)']::text[], '"생각하는 달팽이"는 두려움을 이겨내고 성장하는 사람들의 이야기를 진솔하게 담아내고, 누구든 도전할 수 있는 용기와 희망을 나누는 1인 독립 출판사입니다. 조금 느리더라도 목표를 향해 천천히 그리고 묵묵히 걸어가고 있는 모두의 꿈을 응원합니다.', null, 'https://www.instagram.com/iam_zzzzzzzang/', 381),
  (382, 'B504', null, '선홍빛', 'Sunhongbit', null, null, false, array['문학']::text[], '2021년 ‘고유한 빛깔을 비추는 등불’을 모토로 설립된 선홍빛은 핏빛을 의미하는 출판사명처럼 섬뜩하면서도 아름다운 SF, 호러, 판타지 등의 장르 소설을 출간합니다. 소설가이자 그림 작가인 이부가 운영하는 1인 출판사로, 글과 그림을 모두 다루는 만큼 다양한 장르와 독특한 디자인의 책을 선보입니다.', 'https://sites.google.com/view/sunhongbit', null, 382),
  (383, 'B504', null, '스튜디오 에디트', 'studio_edit', null, null, false, array['예술','문학']::text[], '스튜디오 에디트는 북디자인을 기반으로 한 그래픽디자인 스튜디오입니다. 최근에는 출판, 굿즈, 브랜딩, 강의 등으로 영역을 넓혀가는 중입니다. 스튜디오 에디트만의 아이덴티티 구축이 최종 목표이며, 이를 위해 다방면으로 노력중입니다. 스튜디오 에디트의 성장을 지켜봐주세요.', null, 'https://www.instagram.com/studi0_edit/', 383),
  (384, 'B504', null, '스튜디오블랑', 'STUDIO BLANC', null, null, false, array['총류','예술','문학']::text[], '스튜디오블랑은 창작 스튜디오이자 작가의 오너 출판사로, 사람과 사람 사이의 관계와 감정을 그림과 글로 기록하는 작업을 선보입니다. 사람과의 만남에서 발견한 감정과, 그 위에 더해진 상상을 바탕으로 각자의 순간을 하나의 장면으로 풀어내는 드로잉 에세이, 아트북, 시화집을 제작하고 있습니다. 특히 작가 나소연의 라이브 드로잉 작업은 참여자의 인상과 이야기를 바탕으로 세상에 하나뿐인 장면을 그려내는 방식으로, 독자와의 직접적인 연결을 만들어갑니다. 여백과 서정성을 바탕으로, 스튜디오블랑은 책을 매개로 사람의 순간과 감정을 기록하고 새로운 경험의 가치를 제안합니다.', null, 'https://instagram.com/blancillust/', 384),
  (385, 'B504', null, '쓰는사람', 'SNSR', null, null, false, array['문학']::text[], '출판사이자 글쓰기 모임인 ’쓰는사람’은 우리가 삶에서 무엇을 쓰는 사람인지 모색하고 발견하는 그룹입니다. 글의 힘을 아는 문우들이 모여 다정하고 뭉근한 연대를 이루고 있습니다. 서로의 사유를 나누며 내면의 힘을 기르고, 우리의 글이 더 많은 독자와 만날 수 있는 기회를 발굴하고 있습니다.', 'http://litt.ly/snsr.club', null, 385),
  (386, 'B504', null, '여가도시', 'Yeogadosi', null, null, false, array['예술']::text[], '여가도시는 번아웃과 치열한 일상 속에서 진정한 여유와 지식을 찾는 사람들을 위한 도시·건축·공간·예술 출판사입니다. 감각적인 디자인과 깊이 있는 콘텐츠를 결합해, 공간과 삶의 철학을 담은 책을 만듭니다.', null, 'https://www.instagram.com/yeogadosi/', 386),
  (387, 'B504', null, '여름의서재', 'summerbooks', null, null, false, array['철학','언어','문학']::text[], '여름의서재는 ‘마음돌봄’을 중심 주제로 삼아, 삶을 천천히 들여다보고 스스로를 이해하도록 돕는 책을 만드는 1인 출판사입니다. 치유글쓰기·인문·에세이 분야를 아우르며, 일상의 감정과 생각을 언어로 풀어내는 작업에 주목합니다. 읽기와 쓰기를 통해 자신과 세계를 새롭게 바라보는 경험을 지향하며, 깊이 있는 사유와 따뜻한 시선을 담은 콘텐츠를 꾸준히 선보이고 있습니다. 독자들의 마음돌봄과 성장을 돕는 것이 여름의서재의 중요한 목표입니다.', null, 'https://www.instagram.com/summerbooks_pub/', 387),
  (388, 'B504', null, '유유히', 'UUHEE BOOKS', null, null, false, array['사회과학','문학','기타(만화)']::text[], '2023년 2월에 첫 책을 출간한 유유히는 독자의 작은 가능성을 위한 책을 만드는 출판사입니다. 에세이, 만화, 문학, 인문학 등 분야에 매이지 않고 독자들이 자신도 모르고 있던 작은 가능성을 찾아주는 실용적인 책을 만들고, 책을 읽고 난 뒤 저자와 연결 가능한 만남의 기회를 열고 있습니다.', 'http://www.uuheebooks.com', null, 388),
  (389, 'B504', null, '인생책방/마이북하우스', 'Lifebookstore/Mybookhouse', null, null, false, array['사회과학','언어','전자출판']::text[], '‘마이북하우스(서브 브랜드: 인생책방)’은 인공지능 시대의 창작 도구와 사고법을 적극 활용하되, 그 속에서도 인생책으로 손꼽힐 만큼 재미있고 오래도록 곁에 두고 싶은 책을 만드는 것을 목표로 합니다. 인공지능 기반의 창작도구와 사고법을 활용한 시리즈 기획을 통해 시대의 흐름을 선도하되, 우리의 최종 목표는 언제나 같습니다. “한 권의 책이 누군가의 인생을 바꿀 수 있기를!” 그렇게 우리는 당신의 인생책을 만드는 출판 브랜드, ‘마이북하우스(서브 브랜드: 인생책방)’입니다.', 'http://mybookhouse.com/', null, 389),
  (390, 'B504', null, '정재이프레스', 'j.jaeipress', null, null, false, array['문학']::text[], '정재이프레스는 번역가 겸 작가 정재이가 디렉터이자 대표 저자인 출판사로, 책이 지닌 본연의 목표에 집중하여 독자의 삶에 참여하는 다정한 출판물을 제작합니다. 손수 짓고 큐레이션한 번역서와 창작물을 통해 질문하고 소통합니다. 재이의방과 재이그라피로 세계관을 나누어 각각 울림이 있는 차분한 문학서와 위트 가득한 아트북을 제시합니다.', 'http://jjaeipress.com', 'https://www.instagram.com/j.jaeipress/', 390),
  (391, 'B504', null, '출판사 이베르', 'hiver press', null, null, false, array['예술','문학']::text[], '출판사 이베르''는 동화를 모티브로 한 새로운 형태의 패션 매거진 ''aube(오브)''를 발행하고 있습니다. 프랑스어로 ''이베르''는 ''겨울''을, ''오브''는 ''새벽''을 뜻합니다. 밤이 길어 빛보다 어둠이 익숙한 계절과, 꿈의 가장 깊숙한 곳에 도달한 시간. 겨울잠같이 편안하고 따뜻한 행복감을 드리는 출판사로서, 오브의 페이지를 여는 모든 이들에게 꿈꾸는 듯한 몽환을 선사할 수 있기를 바랍니다.', null, 'https://www.instagram.com/aube_magazine/', 391),
  (392, 'B504', null, '테일브릿지', 'The Tale Bridge', null, null, false, array['사회과학','아동','기타(심리학)']::text[], '“심리학이 사람을 만났습니다.” 심리학자들이 설립한 출판사 테일브릿지는 생의 긴 여정을 관통하는 이야기로 세대와 세대를 잇는 단단한 ''이야기 다리''입니다. 정확하지만 쉽게, 권위 있지만 친절하게 심리학 연구를 일상의 언어로 풀어내어 지금 우리 삶에 꼭 필요한 지혜를 전합니다. 아이들의 마음을 어루만지는 그림 동화부터 어른들의 삶을 깊이 있게 비추는 심리 교양서, 자기계발서, 에세이, 소설까지 다양한 책을 펴냅니다.', null, 'https://www.instagram.com/thetalebridge/', 392),
  (393, 'B504', null, '톰톰프레스', 'TomTom Press', null, null, false, array['예술']::text[], '톰톰프레스는 신비롭고 호기심 많은 검은 고양이 ‘톰톰’에서 영감을 받은 독립 예술 출판사입니다. 고양이를 비롯해 다양한 주제를 탐구하는 아트북과 컬러링북을 선보이며, 단순히 읽거나 소장하는 책을 넘어 예술을 통해 참여하고 영감을 얻으며 위로를 경험할 수 있는 책을 만듭니다. 예술과 상상, 그리고 감성이 만나는 작은 여정을 책 속에 담아냅니다. 또한 소품과 다양한 창작 프로젝트로 영역을 확장하며, 예술이 자연스럽게 일상 속으로 스며드는 경험을 나누는 플랫폼이 되고자합니다.', null, 'https://www.instagram.com/tomtom_press/', 393),
  (394, 'B504', null, '페이지미디어브릿지', 'PMB', null, null, false, array['기타(자기계발)']::text[], 'PMB는 ‘어떻게 살 것인가’라는 근원적인 질문에 답하기 위해 시대를 관통하는 철학적 사유를 일상의 언어로 풀어냅니다. 우리는 단순한 지식 전달을 넘어, 깊은 성찰이 삶의 실천적 변화로 이어지는 ‘지적인 자기계발’을 지향합니다. 내면을 채우는 인문 에세이부터 어제보다 나은 나를 만드는 자기계발서까지, 독자의 삶에 단단한 중심을 세워주는 책을 만듭니다. 한 권의 책이 한 사람의 우주를 바꿀 수 있다는 믿음으로, 당신의 사유가 확장되고 삶이 혁신되는 그 모든 여정에 함께하겠습니다.', 'http://www.pmb.kr', null, 394),
  (395, 'B504', null, '해파리', 'HAEPARY', null, null, false, array['문학','아동']::text[], '"투명하지만 강인한, 작은 존재들을 위한 이야기를 만듭니다." 해파리는 작가 ''김해솔''의 작품을 출판하는 1인 출판사입니다. 속이 훤히 보일 정도로 투명한 해파리는 지구상에 6억년을 살만큼 강인한 생명력을 자랑합니다. 그런 해파리처럼 모든 존재가 자신을 솔직히 드러내더라도 취약해지지 않고 오히려 단단하게 연결되는 세상을 꿈꿉니다.', null, 'https://www.instagram.com/haepary_books/', 395),
  (396, 'B504', null, '혼혼', 'HONHON', null, null, false, array['예술','문학','전자출판']::text[], '혼혼(HONHON)은 아늑하고 부드러운 어둠에서 이야기를 건져 올립니다. 연작소설 「임욱기담집1」과 「검은 고양이 우화집」을 만들었습니다.', null, 'https://www.instagram.com/publisherhonhon/', 396),
  (397, 'B505', null, '쪽프레스', 'JJOKKPRESS', null, null, false, array['총류','예술','문학']::text[], '서울을 기반으로 활동하는 레이블로 콘텐츠에 기반한 여러 형태의 작업을 선보입니다.', 'http://jjokkpress.com', 'https://instagram.com/jjokkpress/', 397),
  (398, 'B506', null, '도서출판도반', 'DOBAN BOOKS', null, null, false, array['철학','종교','문학']::text[], '도서출판 도반은 도서출판 도반은 2009년 송강스님의 금강경 발간을 계기로 불교경전, 스님들의 수행서 등 불교와 관련한 다양한 책들을 꾸준히 출간하면서 불교전문출판사로 자리매김하고 있습니다. 조금 느리더라도 한 권 한 권 진정성 있는 책을 만들어 대장경의 후예 가 되고자 하는 출판사의 이념 아래 닥 섬유 고유의 특성을 담은 전통한지, 안동한지로 한지본 경전도 만들고 있습니다. 천 년의 숨결이 느껴지는 한지에 금강경, 법화경 등 경전들을 고서제본 방식으로 완성도를 높이고 전통과 현대가 어우러진, 출판의 가치를 재창출하고자 노력하고 있습니다.', 'http://dobanbooks.co.kr', 'https://www.instagram.com/dobanbooks/', 398),
  (399, 'B601', null, '안전가옥', 'SAFEHOUSE', null, null, false, array['문학']::text[], '좋은 이야기에는 사람들의 생각을 바꿀 수 있는 힘이 있다고 믿습니다. 그래서 많은 이가 더 좋은 세상을 만들어 나갈 수 있도록 건강한 이야기 생태계를 구축하고, 아직 세상에 드러나지 않은 이야기들을 발굴합니다. 안전가옥은 창작자에게는 든든한 협업 파트너가 되고, 독자에게는 ''재미''와 ''의미''를 담아 좋은 이야기를 만드는 장르 전문 스토리 프로덕션입니다.', 'https://safehouse.kr', 'https://www.instagram.com/safehouse.kr/', 399),
  (400, 'B602', null, '문학동네', 'Munhakdongne', null, null, false, array['총류','철학','종교','사회과학','순수과학','기술과학','공공기관','예술','언어','문학','역사','아동','학습참고서','전자출판','기타']::text[], '문학동네는 신생의 기운으로 팽팽하게 긴장되어 있는 곳, 늘 새로운 활력이 넘치는 곳, 문학 본연의 아름다음과 문학의 자존을 지켜가는 출판사입니다. 문학동네는 국내 작가들의 작품을 소개하는 것뿐 아니라 해외 거장들의 신작도 현지와 시차가 거의 느껴지지 않을 만큼 발 빠르게 소개하는 데 힘쓰고 있습니다. 무엇보다 문학동네소설상, 신인상, 어린이문학상 같은 공모제도를 통해 역량 있는 작가들을 발굴하고, 젊은작가상을 통해 신예작가들의 좋은 작품을 독자들에게 알리려 노력하는 한편, 한국문학을 해외에 소개하는 데도 힘을 기울이고 있습니다.', 'http://www.munhak.com', null, 400),
  (401, 'B603', null, '창비', 'Changbi Publishers', null, null, false, array['총류','철학','종교','사회과학','순수과학','기술과학','공공기관','예술','언어','문학','역사','아동','학습참고서','전자출판','기타']::text[], '한결같되 날로 새롭게, 1966년부터 지금까지 독자와 함께 더 나은 세상을. 한국의 종합출판사로서 문학, 인문, 교양, 어린이, 청소년, 그림책 등 다양한 분야의 양서를 출간하고 있습니다. 또한 교과서 발행, 미디어 서비스 제공, 강좌 운영 등을 통해 새로운 지식문화 창조에 힘쓰고 있습니다. 창비는 최고 수준의 편집과 디자인, 마케팅을 통해 작가가 뛰어난 작품을 생산해낼 수 있도록 지원하며, 책을 매개로 더 나은 세상을 만들어나가는 데 이바지하고자 합니다.', 'https://www.changbi.com/', 'https://www.instagram.com/cafe_changbi/', 401),
  (402, 'B604', null, '아침달', 'ACHIMDAL', null, null, false, array['문학']::text[], '아침달은 2018년 아홉 권의 시집을 동시에 펴내며 그 이름을 알렸습니다. 아침달 시집을 통해 등단과 비등단의 경계를 허물고, 새로운 세계를 보여주는 우수한 작품을 발굴해 소개하며 한국 문단에 새로운 활력을 불어넣는 동시에 문학의 다양성을 추구하는 대안의 장 역할을 해왔습니다. 다양한 삶의 이야기가 담긴 앤솔러지, 독자들이 사랑하는 작가들의 산문집, 아름다운 그림과 글이 함께하는 그림에세이 등을 펴내 문학을 근간으로 보여줄 수 있는 일상을 다채롭게 채색하고 있습니다. 아침달은 여전히 문학이 주는 가치와 즐거움을 믿는 독자들의 성원을 바탕으로 끊임없이 새로운 이야기를 고민하며 성장하고 있습니다. 앞으로도 문학 작품의 저변을 확대하여 모두의 일상을 더 의미 있게 가꾸는 책을 만들겠습니다.', 'http://blog.naver.com/achimdalbooks', null, 402),
  (403, 'B605', null, '다람출판사', 'Darambooks Publishing', null, null, false, array['사회과학','문학','역사']::text[], '다람은 평범한 삶의 감동, 기억해야 할 역사, 그리고 시대의 아픔을 이겨낼 용기와 희망을 나누고 싶다는 소망으로 책을 만들고 있습니다. 2014년 을 시작으로 문학과 인문, 사회서를 주로 펴내고 있으며, 친일 역사의 교훈을 담은 , 일본군 ''위안부'' 피해자 김복동 할머니의 삶을 기록한 , 엄마 작가들의 돌봄 경험을 나눈 등의 베스트셀러가 있습니다. 은 문학나눔 도서로 선정되었고 에세이 시리즈 ''DR mystery''의 는 폴란드 대형 출판사에 판권이 수출되었습니다. 2025년부터는 세계관 공유 앤솔러지 ''얽힘 시리즈''를 통해 새로운 방식으로 한국문학의 가능성을 제시하고 있습니다.', null, 'https://www.instagram.com/darambooks/', 403),
  (404, 'B606', null, '주식회사 휴먼밸류 / 더클래스', 'HUMAN VALUE, THE CLASS', null, null, false, array['총류','사회과학','문학']::text[], '인간의 가치를 오래도록 품는 책을 만듭니다. 더클래스는 시대가 변해도 결코 퇴색되지 않을 ''인간의 가치''를 책에 담습니다. 우리는 복잡한 세상 속에서도 흔들리지 않는 삶의 기준을 제시하고, 독자들이 내면의 품격을 쌓아갈 수 있도록 돕는 지적 동반자가 되고자 합니다. 더클래스의 책 속에는 세상을 바라보는 깊은 시선과 사람을 향한 따뜻한 통찰이 살아 숨 쉽니다.', 'https://www.youtube.com/@choemazon', 'https://www.instagram.com/youtube/', 404),
  (405, 'B607', null, '북챗', 'BOOKCHAT', null, null, false, array['언어','아동','학습참고서']::text[], '북챗은 단순히 책을 읽는 것을 넘어, 직접 쓰고, 생각하고, 발표하는 경험을 통해 성장하도록 돕는 글로벌 언어 출판사입니다. 32권의 오리지널 스토리북 시리즈를 보유하고 있으며, 영어, 한국어, 중국어, 프랑스어, 스페인어, 일본어의 6개 언어로 출판되어 있습니다. 북챗의 목표는 단순히 언어를 배우는 것이 아니라 책이 줄 수 있는 위로와 기쁨, 그리고 자신의 삶을 찾아 나가는 여정을 함께하는 것입니다. 독서를 통해 언어를 배우는 경험은 그 무엇과도 비교할 수 없는 깊은 즐거움이라는 믿음 아래, 이야기 중심의 언어 학습을 지향합니다. 또한 북챗은 아이들의 책은 아이들이 만들어야 한다는 철학으로 어린이작가 시리즈 10권의 출간함으로 자신만의 목소리가 가장 창의적이라는 것을 알고 어린 작가들과 같이 성장합니다.', 'https://www.bookchatkorea.com/', 'https://www.instagram.com/bookchatkorea/', 405),
  (406, 'B608', null, '썸북스', 'SOMEBOOKS', null, null, false, array['예술','문학','기타(그림책)']::text[], '썸북스는 15년째 ''예술로서의 그림책''을 만드는 작가주의 출판사입니다. 글과 그림의 조화는 물론, 종이의 질감과 물리적 형태가 유기적으로 결합된 ''오브제''로서의 가치를 지향합니다. 고정관념을 깨는 조형적 실험과 깊이 있는 사유를 통해, 전 세대의 마음을 잇는 예술적 결실을 선보입니다. 썸북스의 작은 책들이 던지는 질문이 당신의 삶에 깊은 울림이 되기를 바랍니다.', 'http://www.somebooks.kr', null, 406),
  (407, 'B609', null, '국가보훈부', 'Ministry of Patriots and Veterans Affairs', null, null, false, array['총류','철학','종교','사회과학','순수과학','기술과학','공공기관','예술','언어','문학','역사','아동','학습참고서','전자출판','기타']::text[], '국가를 위한 희생과 헌신에 보답하는 보훈은 국가가 마땅히 해야 할 가장 기본적인 책임이자 의무입니다. 국가보훈부는 ‘국가 공동체를 위한 특별한 희생에 특별한 보상’이라는 가치 아래, 독립과 호국, 민주를 아우르는 보훈의 의미를 국민과 함께 나누고자 합니다. 나아가 일상 속 보훈문화 확산과 미래세대를 위한 기억과 계승을 통해, 헌신이 최고의 명예로 존중받는 사회를 만들어가겠습니다.', 'http://www.mpva.go.kr', null, 407),
